 * arithmetic is proved separately by the source-bound lifting certificate. */
#ifndef PROOF_C_SOURCE
#define PROOF_C_SOURCE "../crypto_montgomery_ct.c"
#endif
#include PROOF_C_SOURCE
extern limb_t nondet_limb(void);
extern unsigned nondet_unsigned(void);
int main(void) {
    limb_t modulus[16], upper = 0;
    for (size_t i = 0; i < 16; ++i) {
        modulus[i] = nondet_limb();
        if (i) upper |= modulus[i];
    }
    unsigned scenario = nondet_unsigned();
    unsigned witness = nondet_unsigned();
    __CPROVER_assume(scenario < 5);
    __CPROVER_assume(witness < CRYPTO_MAX_LIMBS);
    crypto_montgomery_ctx ctx;
    limb_t old_word = nondet_limb(), old_inv = nondet_limb();
    size_t old_n = nondet_limb();
    ctx.limbs = old_n; ctx.inverse = old_inv;
    ctx.modulus[witness] = old_word;
    size_t count = scenario == 3 ? 0 : scenario == 4 ? CRYPTO_MAX_LIMBS+1 : 16;
    int rc = crypto_montgomery_ctx_init(scenario == 1 ? (crypto_montgomery_ctx *)0 : &ctx,
                                        scenario == 2 ? (const limb_t *)0 : &modulus[0], count);
    _Bool domain = (modulus[0] & 1) && (upper || modulus[0] > 1);
    if (scenario || !domain) {
        __CPROVER_assert(rc == -1, "setup rejects public errors");
        __CPROVER_assert(errno == (scenario ? EINVAL : EDOM), "setup error code");
        __CPROVER_assert(ctx.limbs == old_n, "setup error preserves length");
        __CPROVER_assert(ctx.inverse == old_inv, "setup error preserves inverse");
        __CPROVER_assert(ctx.modulus[witness] == old_word, "setup error preserves modulus");
    } else {
        __CPROVER_assert(rc == 0 && errno == 0, "setup succeeds for valid modulus");
        __CPROVER_assert(ctx.limbs == 16, "setup stores length");
        if (witness < 16)
            __CPROVER_assert(ctx.modulus[witness] == modulus[witness], "setup copies every modulus limb");
        else
            __CPROVER_assert(ctx.modulus[witness] == 0, "setup clears unused modulus limbs");
    }
    return 0;
}

